function owner(){return {pid:process.pid,birth:birth(process.pid)}}
function identity(o){if(!o||!Number.isSafeInteger(o.pid)||o.pid<1)return 'unknown';try{process.kill(o.pid,0)}catch(e){return e.code==='ESRCH'?'absent':'unknown'}const s=proc(o.pid);if(s&&/^[ZX]$/.test(s.state))return 'absent';return s&&o.birth?(s.birth===o.birth?'same':'other'):'unknown'}
