// A warm request still goes through the core's authoritative full provision path.
// This check only avoids launching an acquisition process when every selected
// recipe is already committed. It never activates a view or fabricates an asset.
function cached(root,plot,spec){try{const old=read(path.join(root,'data.json')),assets={},objects=fs.realpathSync(path.join(root,'.grave','objects'));for(const {id,recipe} of plot.plan(spec)){const a=old.assets?.[id],key=stable([recipe,[process.platform,process.arch],(recipe.needs||[]).map(n=>assets[n].path)]);if(!a||a.key!==key||!fs.realpathSync(a.path).startsWith(objects+path.sep)||stable(read(path.join(a.path,'.plot.json')))!==stable(a)||a.python&&!fs.existsSync(a.python))return false;assets[id]=a}return true}catch{return false}}

function limits(input={}){const l={outputBytes:1048576,timeoutMs:0,...input};if(Object.keys(l).some(k=>!['outputBytes','timeoutMs'].includes(k))||!Number.isSafeInteger(l.outputBytes)||l.outputBytes<0||l.outputBytes>16777216||!Number.isSafeInteger(l.timeoutMs)||l.timeoutMs<0||l.timeoutMs>86400000)throw Error('invalid limits');return l}
function capacity(v){const n=v===undefined||v===''?16:Number(v);if(!Number.isSafeInteger(n)||n<1||n>4096)throw Error('invalid PLOT_RESIDENT_MAX_ACTIVE');return n}
export function request(endpoint,body,timeout=30000){return new Promise((resolve,reject)=>{const c=net.createConnection({host:'127.0.0.1',port:endpoint.port});let bytes=0,parts=[];const stop=e=>{c.destroy();reject(e)};c.setTimeout(timeout,()=>stop(Error('resident request deadline')));c.on('error',reject);c.on('connect',()=>c.end(JSON.stringify({...body,token:endpoint.token})+'\n'));c.on('data',b=>{bytes+=b.length;if(bytes>8388608)return stop(Error('response limit'));parts.push(b)});c.on('end',()=>{try{let {error,...detail}=JSON.parse(Buffer.concat(parts));if(error)throw Object.assign(Error(error),detail,{remote:true});resolve(detail.result)}catch(e){reject(e)}})})}
