// Maps a path inside .grave/objects to its top-level object directory (null outside it).
function objectOf(root,p){const o=fs.realpathSync(path.join(root,'.grave','objects')),r=fs.realpathSync(p);return r.startsWith(o+path.sep)?path.join(o,r.slice(o.length+1).split(path.sep)[0]):null}
const intent=(root,o)=>path.join(root,'.grave','tombstones',path.basename(o)+'.json');
// Pin-then-validate: prune writes its intent before re-reading pins, so either prune sees
// this pin or this validation sees prune's intent. Pins never take the publication lock.
// fast: skip fsync when a durable record written later (a job's submission.json) roots the same paths after a crash.
