function unpin(root,p){if(typeof p==='string'&&path.dirname(p)===path.join(root,'.grave','pins'))fs.rmSync(p,{force:true})}
function jobPaths(root,spec){let m=null;try{m=objectOf(root,self)}catch{}return [...new Set([...Object.values(spec.view.assets).map(a=>a.path),...(m?[m]:[])])]}
async function summary(root,id){try{return await inspect(root,id)}catch(e){return {id,state:'record_error',error:e.message}}}
function load(root,id){return read(path.join(jobDir(root,id),'submission.json'))}
const controlOf=dir=>{const c=optional(path.join(dir,'control.json'))||optional(path.join(dir,'claimed.json'));if(!c?.port||!c.token)throw Error('control unavailable');return c};
const ownerOf=dir=>optional(path.join(dir,'owner.json'))||optional(path.join(dir,'claimed.json'))||optional(path.join(dir,'launch.json'));
