// A job directory without a readable submission cannot have a worker, so it holds no capacity.
function admitted(root,id){const d=jobDir(root,id),st=optional(path.join(d,'status.json'));if(st&&terminal(st.state)||!fs.existsSync(path.join(d,'submission.json')))return null;try{load(root,id)}catch{if(!fs.existsSync(path.join(d,'claimed.json')))return null}return {state:st?.state||'queued'}}
