 // Standby pool (contracts §8). Every lease decision is synchronous and precedes durable acceptance.
 const num=(k,d,lo,hi)=>{const v=process.env[k],n=v===undefined||v===''?d:Number(v);if(!Number.isSafeInteger(n)||n<lo||n>hi)throw Error('invalid '+k);return n};
