export async function start(root,core){root=fs.realpathSync(root);const h=home(root),p=path.join(h,'service.json');try{const e=read(p);await request(e,{op:'ping'},500);return e}catch{}authority(root);const plot=(await import(pathToFileURL(core))).openPlot(root);let view;try{view=await plot.provision('_resident',{use:['resident']})}catch(error){if(!/busy/.test(error.message))throw error;for(let i=0;i<200;i++){try{const e=read(p);await request(e,{op:'ping'},100);return e}catch{}await sleep(25)}throw error}const entry=path.join(view.assets.resident.path,'resident.mjs');const c=spawn(process.execPath,[entry,'--serve',root,core],{detached:true,stdio:'ignore',windowsHide:true});await new Promise((r,j)=>{c.once('spawn',r);c.once('error',j)});c.unref();for(let i=0;i<200;i++){try{const e=read(p);await request(e,{op:'ping'},100);return e}catch{}await sleep(25)}throw Error('supervisor startup failed; inspect resident lock identity')}
export async function cli(root,core,args){const op=args.shift()||'list';let result;if(op==='start'){const e=await start(root,core);result={state:'ready',instance:e.instance}}else if(op==='recover')result=recover(root);else if(op==='prune')result=await prune(root,args.length?JSON.parse(args.join(' ')):{});else{const endpoint=read(path.join(home(root),'service.json'));let body={op};if(op==='submit'){const name=args.shift()||'default';const cmd=args.shift();body={op,name,rid:randomUUID(),...(cmd?{steps:[{cmd,args}]}:{})}}else if(['inspect','cancel'].includes(op))body.id=args.shift();else if(op==='output'){body={op,id:args.shift(),stream:args.shift()||'stdout',offset:Number(args.shift()||0),bytes:Number(args.shift()||65536)}}else if(op==='provision'){body.name=args.shift()||'default';body.spec=args.length?JSON.parse(args.join(' ')):undefined}else if(op==='request')body=JSON.parse(await new Promise((r,j)=>{let a=[],n=0;process.stdin.on('data',b=>{n+=b.length;if(n>MAX_FRAME){j(Error('request limit'));process.stdin.destroy()}else a.push(b)});process.stdin.on('end',()=>r(Buffer.concat(a).toString()));process.stdin.on('error',j)}));result=await request(endpoint,body)}console.log(JSON.stringify(result))}
if(process.argv[1]&&fs.realpathSync(process.argv[1])===self){const a=process.argv.slice(2);try{if(a[0]==='--serve')await serve(a[1],a[2]);else if(a[0]==='--worker')await worker(a[1],validId(a[2]));else if(a[0]==='--standby')await worker(a[1],null,validId(a[2]));else if(a[0]==='--env-host')await envHost(a[1],validId(a[2]),validId(a[3]));else if(a[0]==='--tenant-node')await tenantNode(a[1]);else if(a[0]==='--acquire'){const [,root,core,id,name,raw]=a,p=path.join(home(root),'acquisitions',validId(id)+'.json');atom(p,{...read(p),state:'running',owner:owner()});try{const view=await (await import(pathToFileURL(core))).openPlot(root).provision(name,JSON.parse(raw));atom(p,{...read(p),state:'succeeded',view})}catch(e){atom(p,{...read(p),state:'failed',error:e.message})}}else{let root=path.dirname(path.dirname(self)),core=path.join(root,'main.js');if(a[0]==='--root'){root=path.resolve(a[1]);a.splice(0,2)}await cli(root,core,a)}}catch(e){console.error('[plot resident] '+e.message);process.exitCode=1}}
